from flask import Blueprint, request, jsonify
from app.models.problem import Problem
from app.database import db

def problem_blueprint():
    blueprint = Blueprint('problem', __name__)

    @blueprint.route('/problems', methods=['GET'])
    def get_all_problems():
        try:
            problems = Problem.query.all()
            result = [problem.to_dict() for problem in problems]
            return jsonify(result), 200
        except Exception as e:
            return jsonify({"error": str(e)}), 500

    @blueprint.route('/problems/<int:problem_id>', methods=['GET'])
    def get_problem(problem_id):
        try:
            problem = Problem.query.get(problem_id)
            if problem:
                return jsonify(problem.to_dict()), 200
            return jsonify({"error": "Problem not found"}), 404
        except Exception as e:
            return jsonify({"error": str(e)}), 500

    @blueprint.route('/problems', methods=['POST'])
    def create_problem():
        try:
            data = request.get_json()
            new_problem = Problem(
                title=data.get('title'),
                description=data.get('description'),
                difficulty=data.get('difficulty')
            )
            db.session.add(new_problem)
            db.session.commit()
            return jsonify(new_problem.to_dict()), 201
        except Exception as e:
            db.session.rollback()
            return jsonify({"error": str(e)}), 500

    @blueprint.route('/problems/<int:problem_id>', methods=['PUT'])
    def update_problem(problem_id):
        try:
            data = request.get_json()
            problem = Problem.query.get(problem_id)
            if problem:
                problem.title = data.get('title', problem.title)
                problem.description = data.get('description', problem.description)
                problem.difficulty = data.get('difficulty', problem.difficulty)
                db.session.commit()
                return jsonify(problem.to_dict()), 200
            return jsonify({"error": "Problem not found"}), 404
        except Exception as e:
            db.session.rollback()
            return jsonify({"error": str(e)}), 500

    @blueprint.route('/problems/<int:problem_id>', methods=['DELETE'])
    def delete_problem(problem_id):
        try:
            problem = Problem.query.get(problem_id)
            if problem:
                db.session.delete(problem)
                db.session.commit()
                return jsonify({"message": "Problem deleted successfully"}), 200
            return jsonify({"error": "Problem not found"}), 404
        except Exception as e:
            db.session.rollback()
            return jsonify({"error": str(e)}), 500

    return blueprint

from flask import Blueprint, request, jsonify
from app.models.user import User
from app.database import db

def user_blueprint():
    user_bp = Blueprint('user', __name__, url_prefix='/users')

    @user_bp.route('/', methods=['GET'])
    def get_users():
        try:
            users = User.query.all()
            users_data = [user.to_dict() for user in users]
            return jsonify(users_data), 200
        except Exception as e:
            return jsonify({'error': str(e)}), 500

    @user_bp.route('/<int:user_id>', methods=['GET'])
    def get_user(user_id):
        try:
            user = User.query.get(user_id)
            if not user:
                return jsonify({'error': 'User not found'}), 404
            return jsonify(user.to_dict()), 200
        except Exception as e:
            return jsonify({'error': str(e)}), 500

    @user_bp.route('/', methods=['POST'])
    def create_user():
        try:
            data = request.json
            new_user = User(**data)
            db.session.add(new_user)
            db.session.commit()
            return jsonify(new_user.to_dict()), 201
        except Exception as e:
            db.session.rollback()
            return jsonify({'error': str(e)}), 400

    @user_bp.route('/<int:user_id>', methods=['PUT'])
    def update_user(user_id):
        try:
            user = User.query.get(user_id)
            if not user:
                return jsonify({'error': 'User not found'}), 404

            data = request.json
            for key, value in data.items():
                setattr(user, key, value)
            db.session.commit()
            return jsonify(user.to_dict()), 200
        except Exception as e:
            db.session.rollback()
            return jsonify({'error': str(e)}), 400

    @user_bp.route('/<int:user_id>', methods=['DELETE'])
    def delete_user(user_id):
        try:
            user = User.query.get(user_id)
            if not user:
                return jsonify({'error': 'User not found'}), 404

            db.session.delete(user)
            db.session.commit()
            return jsonify({'message': 'User deleted successfully'}), 200
        except Exception as e:
            db.session.rollback()
            return jsonify({'error': str(e)}), 500

    return user_bp

from flask import Blueprint, request, jsonify
from app.models.solution import Solution
from app.database import db

def solution_blueprint():
    solution_bp = Blueprint('solution', __name__)

    @solution_bp.route('/submit', methods=['POST'])
    def submit_solution():
        try:
            data = request.get_json()
            if not data or 'problem_id' not in data or 'user_id' not in data or 'code' not in data:
                return jsonify({'error': 'Invalid submission data'}), 400

            new_solution = Solution(
                problem_id=data['problem_id'],
                user_id=data['user_id'],
                code=data['code'],
                status='Pending'
            )
            db.session.add(new_solution)
            db.session.commit()
            return jsonify({'message': 'Solution submitted successfully', 'solution_id': new_solution.id}), 201
        except Exception as e:
            db.session.rollback()
            return jsonify({'error': 'An error occurred during submission', 'details': str(e)}), 500

    @solution_bp.route('/solutions/<int:solution_id>', methods=['GET'])
    def get_solution(solution_id):
        try:
            solution = Solution.query.get(solution_id)
            if not solution:
                return jsonify({'error': 'Solution not found'}), 404

            return jsonify({
                'solution_id': solution.id,
                'problem_id': solution.problem_id,
                'user_id': solution.user_id,
                'code': solution.code,
                'status': solution.status,
                'submitted_at': solution.submitted_at
            }), 200
        except Exception as e:
            return jsonify({'error': 'An error occurred while fetching solution', 'details': str(e)}), 500

    return solution_bp

